import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {CLASSIC_SYMBOLS,classicSymbol as s,classicResult} from './ClassicFeature';
export class ClassicPreviewSlot extends SlotMain {
 constructor(private readonly fixture='multiple'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'realtime-vegas',title:'레트로 히트',subtitle:'RETRO HIT',tag:'무료 피처 초안',color:'#402c32',accent:'#eec562',description:'5릴 · 3행 · 5라인 원판 참고\n과일 연속 당첨 · 라인별 지급\n레몬과 자두 복수 히트\n스캐터 상세 규칙은 조사 중',symbols:CLASSIC_SYMBOLS.map((name,i)=>({id:s(name),name:['체리','레몬','오렌지','자두','포도','수박','7','SCATTER'][i],color:'#eec562',weight:0,payout:0}))};
 spin():SpinResult{throw Error('Classic draft is free playback only');}
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Classic art');return 'slot-art-handcrafted-v1/realtime-vegas/'+id.slice('realtime-vegas-'.length);}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const board=['scatter','watermelon','orange','seven','seven','lemon','lemon','lemon','lemon','lemon','plum','plum','plum','plum','orange'].map(s);
  if(this.fixture==='no-win')return classicResult(Array.from({length:15},(_,cell)=>s(CLASSIC_SYMBOLS[cell%7])),[],bet);
  if(this.fixture==='seven'){[5,6,7,8,9].forEach(cell=>board[cell]=s('seven'));return classicResult(board,[{line:0,symbol:s('seven'),amount:bet*10,cells:[5,6,7,8,9]}],bet);}
  const wins=[{line:0,symbol:s('lemon'),amount:bet*4,cells:[5,6,7,8,9]}];if(this.fixture!=='single')wins.push({line:2,symbol:s('plum'),amount:bet*2,cells:[10,11,12,13]});return classicResult(board,wins,bet);
 }
}
