import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
/** Coin Grab adaptation. Original jackpot amounts and trigger odds are not published. */
export class OilPrizeSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){
  super(spec);this.config.symbols.find(s=>s.id===this.id('coin'))!.weight=12;this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=0;
  for(const name of ['barrel','portrait','boom'])this.config.symbols.push({id:this.id(name),name,color:'#e7ad60',weight:0,payout:0});
  this.config.description='5×3 · 25라인 · 왼쪽부터 연결\n상금 코인 6개 이상: 현재 코인을 고정하고 리스핀 3회로 진입합니다.\n새 코인이 멈추면 남은 횟수를 3회로 복구합니다. 빈칸만 회전하며 종료 시 고정 상금을 한 번씩 회수합니다.\n파란 배럴은 고정 티어 상금입니다. 15칸 완성 시 유전 완성 상금을 추가합니다.\n트리거·확률·티어 금액은 로컬 규칙이며 서버 공유 잭팟은 적용하지 않습니다.';
 }
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-oil';}
 private prizeValue(rng:()=>number){const r=rng();return r<.5?1:r<.75?2:r<.9?5:r<.97?10:r<.987?15:r<.996?30:r<.9995?60:100;}
 private hold(board:string[],bet:number,rng:()=>number,base:SpinResult,initial?:Map<number,number>){
  const values=initial||new Map<number,number>(cells(board,this.id('coin')).map(c=>[c,this.prizeValue(rng)])),rounds=[base],snapshots:ExpansionFrame[]=[];let left=3;
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],previous=Array.from(values.keys()))=>{const b=Array.from({length:15},(_,c)=>values.has(c)?this.id(values.get(c)!>=15?'barrel':'coin'):''),f=this.frame(b,action,caption,focus,{held:previous,remaining:left,panel:{label:'OIL VAULT',values:[values.size,15],columns:2}});snapshots.push(f);return f;};
  rounds.push(this.round(bet,[frame('state','유전 상금 고정 · 리스핀 3회')]));
  while(left>0&&values.size<15){left--;const previous=Array.from(values.keys()),landed:number[]=[];for(let c=0;c<15;c++)if(!values.has(c)&&rng()<.075){values.set(c,this.prizeValue(rng));landed.push(c);}const fs=[frame('reels','고정 유전 상금 유지 · 빈칸 회전',[],previous)];if(landed.length){left=3;fs.push(frame('effect','유전 분출 · 새 상금 고정 · 3회 복구',landed));}fs.push(frame('state','남은 리스핀 '+left+'회'));rounds.push(this.round(bet,fs));}
  left=0;const paid=frame('collect','유전 파이프 → 고정 상금 한 번씩 회수',Array.from(values.keys()));paid.wins=Array.from(values).map(([cell,value]):Win=>({line:-1,symbol:this.id(value>=15?'barrel':'coin'),cells:[cell],amount:Math.round(bet*value*this.payoutFactor),multiplier:value*this.payoutFactor}));
  const awards=new Map(paid.wins.map(w=>[w.cells[0],w]));for(const f of base.expansionFeature!.frames)if(f.coinAwards)f.coinAwards=f.coinAwards.map(a=>({cell:a.cell,win:awards.get(a.cell)!}));for(const f of snapshots)f.coinAwards=f.board.flatMap((id,cell)=>id?[{cell,win:awards.get(cell)!}]:[]);
  const fs=[paid];if(values.size===15)fs.push(this.prize(paid.board,bet,100,Array.from(values.keys()),'15칸 완성 · 유전 완성 상금'));
  rounds.push(this.round(bet,fs));return this.finish(rounds,{featureOnly:true});
 }
 play(board:string[],bet:number,rng:()=>number){
  this.validate(board,bet);const base=this.ordinary(board,bet),coins=cells(board,this.id('coin')),values=new Map(coins.map(c=>[c,this.prizeValue(rng)])),preview=coins.map(cell=>({cell,win:{line:-1,symbol:this.id('coin'),cells:[cell],amount:Math.round(bet*values.get(cell)!*this.payoutFactor),multiplier:values.get(cell)!*this.payoutFactor}}));
  for(const f of base.expansionFeature!.frames)f.coinAwards=preview;
  if(coins.length<6)return this.finish([base]);const trigger=this.frame(board,'trigger','상금 코인 '+coins.length+'개 · 유전 고정 보너스',coins);trigger.coinAwards=preview;base.expansionFeature!.frames.push(trigger);return this.hold(board,bet,rng,base,values);
 }

 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const order=Array.from({length:15},(_,i)=>i);for(let i=14;i>0;i--){const j=randomIndex(rng,i+1);[order[i],order[j]]=[order[j],order[i]];}const initial=new Set(order.slice(0,6)),pool=this.config.symbols.filter(s=>s.weight>0&&s.id!==this.id('coin')),board=Array.from({length:15},(_,c)=>initial.has(c)?this.id('coin'):pool[randomIndex(rng,pool.length)].id),base=this.round(bet,[this.frame(board,'trigger','독립 유전 상금 보너스 구매',Array.from(initial))]);return this.purchaseFromResult(this.hold(board,bet,rng,base));}
}
