import {SlotMain,SlotConfig,SpinResult,Win,SymbolSpec} from './SlotMain';
export type Random=()=>number;
export const choose=<T>(items:T[],rng:Random):T=>items[Math.min(items.length-1,Math.floor(rng()*items.length))];
export const sampleCells=(n:number,count:number,rng:Random)=>{const pool=Array.from({length:n},(_,i)=>i),out:number[]=[];while(out.length<count&&pool.length)out.push(pool.splice(Math.min(pool.length-1,Math.floor(rng()*pool.length)),1)[0]);return out;};
export function makeLines(rows:number,count:number){
 const routes:number[][]=[];
 const add=(r:number[])=>{if(!routes.some(old=>old.every((v,i)=>v===r[i])))routes.push(r);};
 for(let r=0;r<rows;r++)add(Array(5).fill(r));
 for(let start=0;start<rows;start++)for(const direction of [1,-1])add(Array.from({length:5},(_,c)=>{const p=((start+c*direction)%(2*rows-2)+2*rows-2)%(2*rows-2);return p<rows?p:2*rows-2-p;}));
 for(let a=0;a<rows;a++)for(let b=0;b<rows;b++)for(let c=0;c<rows;c++)add([a,b,c,b,a]);
 return routes.slice(0,count).map(line=>line.map((r,c)=>r*5+c));
}
export interface FeatureDefinition {id:string;title:string;subtitle:string;colors:string[];names:string[];rules:string[];source:string;maxWin:number;rows:number;lines:number;topPays:number[];}
/** Shared arithmetic and settlement; each subclass owns its actual feature state machine. */
export abstract class FeatureGame extends SlotMain {
 readonly config:SlotConfig;readonly columns:number=5;readonly rows:number;readonly hasBonus=true;readonly maxWin:number;readonly paylines:number[][];
 readonly paytable:number[][];readonly definition:FeatureDefinition;
 get unlockPriceTenths(){return 1000;}get bonusSymbol(){return this.config.id+'-14';}get wildSymbol(){return this.config.id+'-wild';}
 constructor(def:FeatureDefinition){super();this.definition=def;this.rows=def.rows;this.maxWin=def.maxWin;this.paylines=makeLines(def.rows,def.lines);
  this.paytable=def.topPays.map(p=>[0,0,Math.round(p*10)/100,Math.round(p*35)/100,p]);
  const symbols:SymbolSpec[]=def.names.map((name,i)=>({id:def.id+'-'+i,name,art:['cat','gem','star','key','bell','bottle','leaf','gear'][i%8],color:def.colors[1],weight:i<def.topPays.length?5+i*3:0,payout:i<def.topPays.length?def.topPays[i]:0}));
  symbols.push({id:def.id+'-wild',name:'WILD',art:'star',color:'#ffe2a0',weight:0,payout:0});
  this.config={id:def.id,title:def.title,subtitle:def.subtitle,tag:'FEATURE',color:def.colors[0],accent:def.colors[1],description:def.rules.join('\n'),symbols};
 }
 protected rollBoard(rng:Random){return Array.from({length:this.columns*this.rows},()=>this.pick(rng));}
 protected scatter(board:string[],rng:Random,count=3){for(const cell of sampleCells(board.length,count,rng))board[cell]=this.bonusSymbol;}
 protected count(board:string[],id:string){return board.filter(s=>s===id).length;}
 evaluate(board:string[],bet:number,values=Array(this.columns*this.rows).fill(1),shared=0):SpinResult{
  if(board.length!==this.columns*this.rows||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid feature board');
  const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;
   for(let s=0;s<this.definition.topPays.length;s++){const symbol=this.config.symbols[s].id;let count=0,m=0;for(const cell of line){if(board[cell]!==symbol&&board[cell]!==this.wildSymbol)break;count++;if(board[cell]===this.wildSymbol)m+=values[cell]||1;}
    const multiplier=m?shared||m:1,amount=Math.round(bet*(this.paytable[s][count-1]||0)*multiplier);
    if(amount&&(!best||amount>best.amount))best={line:index,symbol,cells:line.slice(0,count),amount,multiplier};
   }if(best)wins.push(best);
  });return {board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),symbolValues:[...values]};
 }
 protected addCash(result:SpinResult,cells:number[],multiple:number,caption:string){if(multiple<=0)return;const amount=Math.round(result.bet*multiple),win={line:-1,symbol:this.config.id+'-10',cells:[...cells],amount};result.wins.push(win);result.payout+=amount;result.featureText=caption;}
 protected finish(rounds:SpinResult[],featureName:string,awarded=0):SpinResult{
  let left=rounds[0].bet*this.maxWin;
  for(const r of rounds){for(const w of r.wins){w.amount=Math.min(left,w.amount);left-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);r.cascades?.forEach(c=>c.payout=c.wins.reduce((n,w)=>n+w.amount,0));}
  if(rounds.length===1)return rounds[0];
  return {board:[...rounds[rounds.length-1].board],bet:rounds[0].bet,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),rounds,featureName,freeSpinsAwarded:awarded};
 }
 demoSpin(bet:number){let n=837;const rng=()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296;};for(let i=0;i<10000;i++){const r=this.spin(bet,rng);if(r.payout>0&&!r.rounds)return r;}return this.spin(bet,rng);}
}
