import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
export const ANIMAL_LINES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
/** Eight directions, paid once each. Fixed independent sampling: no wallet/history adjustment. */
export class AnimalLinesSlot extends SlotMain {
 readonly hasBonus=true;get bonusSymbol(){return 'frog';}
 readonly paylines=ANIMAL_LINES;
 readonly config:SlotConfig={id:'animal-lines',title:'동물 삼목',subtitle:'ANIMAL TRIO',tag:'8 DIRECTIONS',color:'#315f6c',accent:'#aee4ce',description:'가로·세로·대각선 모두 당첨!\n3×3 보드에서 같은 동물 세 마리를 맞추세요.',symbols:[
  {id:'rabbit',name:'토끼',color:'#f4dfd5',weight:1,payout:1},{id:'cat',name:'고양이',color:'#e7b581',weight:1,payout:2},{id:'dog',name:'강아지',color:'#d8bd91',weight:1,payout:3},{id:'fox',name:'여우',color:'#e59a73',weight:1,payout:4},{id:'panda',name:'판다',color:'#bbc9b8',weight:1,payout:5},{id:'bear',name:'곰',color:'#b99478',weight:1,payout:10},{id:'frog',name:'개구리',color:'#97b888',weight:0.45263671875,payout:30},{id:'chick',name:'병아리',color:'#ead287',weight:.47767446989397566,payout:120}]};
 spin(bet:number,rng:()=>number=Math.random):SpinResult{return this.freeSpinSequence(super.spin(bet,rng),()=>super.spin(bet,rng),round=>round.board.filter(id=>id==='frog').length>=3?6:0);}
 evaluate(board:string[],bet:number):SpinResult{if(board.length!==9||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid animal trio board');const wins:Win[]=[];this.paylines.forEach((cells,line)=>{if(cells.every(i=>board[i]===board[cells[0]])){const symbol=this.config.symbols.find(s=>s.id===board[cells[0]])!;wins.push({line,symbol:symbol.id,cells:[...cells],amount:bet*symbol.payout});}});return {board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0)};}
 demoSpin(bet:number){return this.evaluate(['cat','rabbit','dog','cat','cat','cat','cat','fox','cat'],bet);}
}
