// Flat, light colours keep pixel silhouettes readable without making every
// machine use the same ivory plate. Feature and winning plates take precedence.
const families = [
 {color:'#c9e9d8',slots:['animal-lines','frog-crown-pond','jungle-height-fortune','dog-yard-original','rabbit-bingo-garden','frog-story-chapters']},
 {color:'#c4e2f4',slots:['polar-tiger-path','white-peak-impact','tundra-two-way','wolf-gold-moon','cruise-feature-builder','mirror-manor-reels']},
 {color:'#dccff0',slots:['moon','potion-purse-tower','feline-double-trails','renaissance-gem-fall','serpent-gaze-reels','angel-devil-contract']},
 {color:'#f1d0dd',slots:['cherry','puppy-paris-path','heart-link-vault','cat-diamond-promotion','city-linked-prize']},
 {color:'#f5d4bf',slots:['sunset-road-wheel','festival-drum-choice','lantern-fire-link','oil-prize-boom','sumo-ring-hold']},
 {color:'#eee4ae',slots:['animal','season-tile-garden','bear-honey-prize','four-cart-gold','sun-goddess-stack','stone-king-collector']},
 {color:'#bfe8e5',slots:['lobster-harbor-choice','lobster-harbor-ways','nile-queen-double','coin-rail-express','silver-mine-hold','rhino-grand-ways']},
 {color:'#cfdcf5',slots:['twin-circuit','cosmic-herd-cascade','midnight-sticky-rail','wolf-stack-ridge','thunder-kept-respin','dragon-ember-vault']},
 {color:'#d6e4bb',slots:['clockwork','wind-house-frames','builder-house-rise','joey-puzzle-trail','prairie-buffalo-king','buffalo-diamond-pot','harvest-moon-fiesta','relic-discovery-ledger','bison-daily-trail']},
];
const slotColors:Record<string,string>={};
for(const family of families)for(const slot of family.slots)slotColors[slot]=family.color;

export function reelCellBackground(slotId:string):string {
 if(slotColors[slotId])return slotColors[slotId];
 // Stable fallback also gives existing and future machines varied light plates.
 let hash=0;
 for(let i=0;i<slotId.length;i++)hash=(Math.imul(hash,31)+slotId.charCodeAt(i))>>>0;
 return families[hash%families.length].color;
}
