import {NativeURL} from '../vendor/firebase-sdk.js';
/** Cocos 3.8.8 exposes withCredentials as a getter-only placeholder.
 * Firestore's HTTP transactions assign it before sending and can throw there.
 * JSB has no browser cookie/CORS mode; Firebase authenticates with its ID-token
 * header. Keep a writable per-request flag without changing those headers.
 */
export function installNativeXHRCompatibility(scope:typeof globalThis=globalThis):void {
 // Cocos's Blob URL shim depends on a browser anchor element and throws
 // when Firestore parses an HTTPS RPC address. Use a real URL parser.
 try{if(new scope.URL('https://firestore.googleapis.com/v1/test').host!=='firestore.googleapis.com')throw Error('URL parser unavailable');}
 catch{const original=scope.URL;const parser=NativeURL;if(original?.createObjectURL)parser.createObjectURL=original.createObjectURL.bind(original);if(original?.revokeObjectURL)parser.revokeObjectURL=original.revokeObjectURL.bind(original);scope.URL=parser;}
 // Firebase local persistence polls on mobile; JSB has no StorageEvent.
 if(typeof scope.StorageEvent==='undefined')scope.StorageEvent=class {
  readonly type:string;readonly key:string|null;readonly oldValue:string|null;readonly newValue:string|null;
  constructor(type:string,init:StorageEventInit={}){this.type=type;this.key=init.key??null;this.oldValue=init.oldValue??null;this.newValue=init.newValue??null;}
 } as unknown as typeof StorageEvent;
 const NativeXHR=scope.XMLHttpRequest;
 if(!NativeXHR)return;
 let prototype=NativeXHR.prototype,descriptor:PropertyDescriptor|undefined;
 while(prototype&&!descriptor){descriptor=Object.getOwnPropertyDescriptor(prototype,'withCredentials');prototype=Object.getPrototypeOf(prototype);}
 if(!descriptor?.get||descriptor.set)return;
 const CompatibleXHR=function(){
  const xhr=new NativeXHR();
  Object.defineProperty(xhr,'withCredentials',{value:false,writable:true,configurable:true});
  return xhr;
 } as unknown as typeof XMLHttpRequest;
 CompatibleXHR.prototype=NativeXHR.prototype;
 Object.setPrototypeOf(CompatibleXHR,NativeXHR);
 scope.XMLHttpRequest=CompatibleXHR;
}
