import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {TUT_LINES,TUT_ART,tutSymbol,tutRound} from './TutRules';
import {tutSequence} from './TutSequence';
export {TUT_LINES,TUT_PAYS,TUT_ART,tutSymbol,tutRound} from './TutRules';
const ID='hunter-book-tutu';
/** Isolated art/ordinary-then-expansion playback. No natural or purchased play. */
export class TutPreviewSlot extends SlotMain {
 constructor(private readonly fixture='expansion'){super();}
 get bonusSymbol(){return tutSymbol(9);}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines=TUT_LINES;
 readonly bets=[...BET_LEVELS];readonly maxWin=5500;
 readonly config:SlotConfig={id:ID,title:'헌터와 투투의 책',subtitle:'HUNTER AND TUTU’S BOOK',tag:'전용 아트 · 무료 검수',color:'#40556b',accent:'#dbac48',description:'일반 지급 뒤 비인접 릴 선택 심볼 확장',symbols:TUT_ART.map((_,i)=>({id:tutSymbol(i),name:['탐험가','유적 수호자','고양이','풍뎅이','A','K','Q','J','10','책 WILD/SCATTER'][i],color:'#dbac48',weight:0,payout:0}))};
 artResource(id:string){const index=this.config.symbols.findIndex(s=>s.id===id);if(index<0)throw Error('Unknown Tut art');return 'slot-art-delivered-v1/'+ID+'/v05/'+TUT_ART[index];}
 spin(_bet?:number,_rng?:()=>number):SpinResult{throw Error('Tut preview is not a live game');}
 demoSpin(bet:number):SpinResult{
  if(this.fixture==='bonus'||this.fixture==='retrigger'||this.fixture==='max-win')return this.bonusFixture(bet);
  if(this.fixture==='no-win')return tutRound(Array.from({length:15},(_,i)=>4+i%5),bet);
  const board=Array.from({length:15},(_,i)=>4+(i+Math.floor(i/5))%5);
  if(this.fixture==='scatter'){board[0]=board[7]=board[14]=9;return tutRound(board,bet);}
  if(this.fixture==='ordinary'){board[5]=board[6]=0;return tutRound(board,bet);}
  board[0]=board[14]=0;
  // Separate normal line win first, then selected high symbol expands on reels1/5.
  board[5]=board[6]=board[7]=4;
  return {...tutRound(board,bet,0),featureText:'탐험가 · 비인접 릴 확장'};
 }
 /** Deterministic free playback only. Natural reel probabilities remain unverified. */
 private bonusFixture(bet:number):SpinResult{
  const trigger=Array.from({length:15},(_,i)=>4+(i+Math.floor(i/5))%5);
  trigger[0]=trigger[7]=trigger[14]=9;
  return tutSequence(trigger,bet,0,state=>{
   if(this.fixture==='max-win')return Array(15).fill(0);
   const board=Array.from({length:15},(_,i)=>4+(i+Math.floor(i/5))%5);
   if(state.played===1)board[0]=board[14]=0;
   if(this.fixture==='retrigger'&&state.played===10)board[0]=board[7]=board[14]=9;
   return board;
  });
 }
}
