import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {DIGIT_NUMBERS,DIGIT_DECOR,digitSymbol,digitResult} from './DigitFeature';

export class DigitPreviewSlot extends SlotMain {
 constructor(private readonly fixture='boost'){super();}
 readonly columns=5;readonly rows=1;readonly mode='lines' as const;readonly paylines=[[0,1,2,3,4]];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'double-lucky',title:'네온 넘버 링크',subtitle:'NEON NUMBER LINK',tag:'무료 피처 초안',color:'#372449',accent:'#e6b9eb',description:'5릴 · 1라인\n인접 숫자를 이어 붙여요\n연결한 값 ÷100 × 총 베팅\n럭키 넘버는 한 숫자를 키워요',symbols:[...DIGIT_NUMBERS,...DIGIT_DECOR].map(value=>({id:digitSymbol(value),name:typeof value==='number'?String(value):({'bar':'BAR','double-bar':'BAR 2','triple-bar':'BAR 3','chip':'CHIP','dice':'DICE'}[value]),color:'#e6b9eb',weight:0,payout:0}))};
 spin(_bet?:number,_rng?:()=>number):SpinResult{throw Error('Digit draft is free playback only');}
 artResource(id:string){const name=id.slice('double-lucky-'.length);if(!this.config.symbols.some(s=>s.id===id))throw Error('Unknown Digit art');return 'slot-art-handcrafted-v1/double-lucky/'+(/^\d+$/.test(name)?'number-tile':name);}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  if(this.fixture==='no-win')return digitResult(['bar','chip','dice','double-bar','triple-bar'],[],bet);
  if(this.fixture==='split')return digitResult([7,55,'dice',91,5],[[0,1],[3,4]],bet);
  if(this.fixture==='all')return digitResult([9,9,7,1,1],[[0,1,2,3,4]],bet);
  if(this.fixture==='ordinary')return digitResult(['bar','bar','bar',9,5],[[3,4]],bet,undefined,[{line:0,symbol:digitSymbol('bar'),cells:[0,1,2],amount:bet*2}]);
  return digitResult([4,8,4,'bar',4],[[0,1,2]],bet,{cell:1,before:8,after:36});
 }
}
