import {drawReelBoard} from './ReelScatter';
import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
export const WALNUT_ID='walnut-toy-workshop';
export const walnutSymbol=(name:string|number)=>WALNUT_ID+'-'+name;
export const WALNUT_MASKS=['green','blue','purple','owl','pumpkin'];
export interface WalnutStep {cell:number;kind:'advance'|'mask';mask?:number;before:number[];after:number[];win?:Win;}
export interface WalnutPlayback {before:number[];after:number[];steps:WalnutStep[];}
/** Five-spin conveyor and five monster awards are gameplay-video references.
 * Trigger count, star movement, mask progression, weights and base paytable
 * below are a local adaptation pending the original social game's help. */
export class WalnutWorkshopSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 readonly bonusCalibrationKey=WALNUT_ID+':conveyor-v1';get bonusSymbol(){return walnutSymbol('star');}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'별 메달이 공방을 엽니다',triggerText:'호두 컨베이어 가동',bonusInText:'slot.walnutToyWorkshop.bonusInText',hitText:'장난감 라인 완성',totalWinText:'공방 총 보상',signature:'별 메달 운반 · 다섯 호두 배수',uiEffect:'컨베이어 이동 후 호두 열기',soundCue:'featureLand',anticipationHold:.3,hitHold:.2,outHold:.5};
 readonly config:SlotConfig={id:WALNUT_ID,title:'호두 장난감 공방',subtitle:'WALNUT TOY WORKSHOP',tag:'WALNUT CONVEYOR · FIVE SPINS',color:'#4b363b',accent:'#e3b878',description:'5×3 · 25라인\n별 메달 3개 이상: 호두 공방 5회\n공방의 별은 다섯 호두 배수를 1씩 올립니다(최대 ×10)\n괴물 호두는 1/2/3/5/10배 × 현재 배수 지급\n공방은 릴 한 세트 · 5회 종료 · 재진입 없음',symbols:[...['장난감 장인','기관차','목마','곰 인형','장난감 북','A','K','Q','J'].map((name,n)=>({id:walnutSymbol(n),name,color:'#e3b878',weight:[4,5,6,7,8,12,13,14,15][n],payout:[4,3,2.5,2,1.5,.8,.7,.6,.5][n]})),...['star','walnut',...WALNUT_MASKS].map((name,i)=>({id:walnutSymbol(name),name:['별 메달','호두','초록 괴물','파랑 괴물','보라 괴물','부엉이','호박'][i],color:'#e3b878',weight:i===0?4.2:0,payout:0}))]};
 evaluate(board:string[],bet:number):SpinResult{if(!this.bets.includes(bet)||board.length!==15||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid walnut spin');const wins:Win[]=[];WOLF_LINES.forEach((line,index)=>{const n=this.config.symbols.findIndex(s=>s.id===board[line[0]]);if(n<0||n>=9)return;const cells:number[]=[];for(const c of line){if(board[c]!==walnutSymbol(n))break;cells.push(c);}if(cells.length>=3){const multiple=this.config.symbols[n].payout*[.1,.35,1][cells.length-3];wins.push({line:index,symbol:walnutSymbol(n),cells,amount:Math.round(bet*multiple),multiplier:multiple});}});return{board:[...board],bet,wins,payout:wins.reduce((s,w)=>s+w.amount,0),presentation:this.presentation};}
 private freeRound(bet:number,rng:()=>number,state:number[]):SpinResult{
  const starColumns=new Set<number>(),before=[...state],steps:WalnutStep[]=[],wins:Win[]=[],board=Array.from({length:15},(_,cell)=>{const roll=rng();if(roll<.04&&!starColumns.has(cell%5)){starColumns.add(cell%5);return walnutSymbol('star');}return roll<.16?walnutSymbol(WALNUT_MASKS[Math.min(4,Math.floor(rng()*rng()*5))]):walnutSymbol('walnut');});
  // Resolve in reel order. A later star cannot change an earlier mask's award.
  for(let col=0;col<5;col++)for(let row=0;row<3;row++){const cell=row*5+col,id=board[cell],old=[...state];if(id===walnutSymbol('star')){for(let m=0;m<5;m++)state[m]=Math.min(10,state[m]+1);steps.push({cell,kind:'advance',before:old,after:[...state]});}else{const mask=WALNUT_MASKS.findIndex(m=>id===walnutSymbol(m));if(mask>=0){const multiple=[1,2,3,5,10][mask]*state[mask],win:Win={line:-2,symbol:id,cells:[cell],amount:bet*multiple,multiplier:multiple};wins.push(win);steps.push({cell,kind:'mask',mask,before:old,after:[...state],win});}}}
  return{board,bet,wins,payout:wins.reduce((s,w)=>s+w.amount,0),walnutFeature:{before,after:[...state],steps},presentation:this.presentation};
 }
 private sequence(base:SpinResult,rng:()=>number){const state=[1,1,1,1,1],result=this.freeSpinSequence(base,()=>this.freeRound(base.bet,rng,state),r=>r===base?5:0);result.presentation=this.presentation;result.featureName='호두 컨베이어 5회';result.bonusEndReason=result.payout>=base.bet*this.maxWin?'max-win':'spins-exhausted';return result;}
 spin(bet:number,rng:()=>number=Math.random){const base=this.evaluate(drawReelBoard(5,3,this.config.symbols,this.bonusSymbol,rng),bet);return base.board.filter(id=>id===this.bonusSymbol).length>=3?this.sequence(base,rng):base;}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid walnut bet');const board=Array.from({length:15},(_,i)=>walnutSymbol(i%9));for(const c of [0,6,12])board[c]=this.bonusSymbol;const base={board,bet,wins:[],payout:0,presentation:this.presentation};const result=this.sequence(base,rng);result.bonusTriggerRound=base;result.rounds=result.rounds!.slice(1);result.wins=result.rounds.flatMap(r=>r.wins);result.payout=result.wins.reduce((s,w)=>s+w.amount,0);return result;}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>walnutSymbol((i+Math.floor(i/5))%9));board[5]=board[6]=board[7]=walnutSymbol(1);return this.evaluate(board,bet);}
 bonusDemoSpin(bet:number){let seed=412;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};return this.prepareBonusPurchase(bet,rng);}
}
