import {vikingOrdinaryCascade,VikingCascadeResult} from './VikingCascade';
import {VikingProgress} from './VikingProgress';
import {vikingRagnarokMultiplier} from './VikingFeatures';
import {vikingFenrir,vikingJormungandr,vikingSurtr,VikingFireGroup} from './VikingDestruction';
import {vikingLoki} from './VikingLoki';

export type VikingDestructionPlan =
 | {kind:'fenrir';lines:{cells:number[];action:'remove'|'transform'}[];target:number}
 | {kind:'jormungandr';path:number[];converted:number[];target:number}
 | {kind:'surtr';groups:VikingFireGroup[]}
 | {kind:'loki';removedType:number;transformedType:number;targetType:number};
export type VikingDestructionKind=VikingDestructionPlan['kind'];
type Refill=(column:number,row:number)=>number;
export function vikingExecuteDestruction(board:readonly number[],plan:VikingDestructionPlan,refill:Refill){
 switch(plan.kind){
  case 'fenrir':return vikingFenrir(board,plan.lines,plan.target,refill);
  case 'jormungandr':return vikingJormungandr(board,plan.path,plan.converted,plan.target,refill);
  case 'surtr':return vikingSurtr(board,plan.groups,refill);
  case 'loki':return vikingLoki(board,plan.removedType,plan.transformedType,plan.targetType,refill);
  default:throw Error('Unknown Viking destruction effect');
 }
}
export type VikingDestructionResult=ReturnType<typeof vikingExecuteDestruction>;
export type VikingRagnarokEvent=
 | {kind:'cascades';segment:VikingCascadeResult}
 | {kind:'destruction';effect:VikingDestructionResult};
const KINDS:VikingDestructionKind[]=['fenrir','jormungandr','surtr','loki'];

/** One Ragnarok round: resolve ALL wins, then use one unused destruction,
 * and repeat until all four have run and the last resulting cascades finish.
 * This path accepts ordinary symbols and unambiguous god WILD substitution
 * plus researched explicit effect plans. It does
 * not invent selection odds, overlapping/pure-WILD settlement, entry-board generation or the
 * still-unverified multiplier scope relative to the triggering base win.
 * Hence it returns an unmultiplied subtotal, never a payable SpinResult.
 */
export function vikingRagnarok(
 initial:readonly number[],bet:number,
 hooks:{
  plan:(board:readonly number[],remaining:readonly VikingDestructionKind[])=>VikingDestructionPlan;
  refill:Refill;
 },
 state:{progress?:VikingProgress;maxCascadeSteps?:number}={},
){
 let board=[...initial],charge=0,subtotal=0,progress=state.progress;
 const remaining=[...KINDS],events:VikingRagnarokEvent[]=[];
 while(true){
  // Setting ragnarokPlayed prevents recursive charge/Ragnarok triggers while
  // preserving symbol counts, individual wins and growing-bonus progress.
  const segment=vikingOrdinaryCascade(board,bet,hooks.refill,{charge,subtotal,progress,ragnarokPlayed:true,maxSteps:state.maxCascadeSteps});
  events.push({kind:'cascades',segment});
  board=[...segment.board];charge=segment.charge;subtotal=segment.subtotal;progress=segment.progress;
  if(!remaining.length)break;
  const plan=hooks.plan([...board],[...remaining]);
  const index=remaining.indexOf(plan.kind);
  if(index<0)throw Error('Ragnarok destruction must be unused');
  const effect=vikingExecuteDestruction(board,plan,hooks.refill);
  remaining.splice(index,1);
  events.push({kind:'destruction',effect});
  board=[...effect.after];
 }
 return {board,events,winningSymbols:charge,unmultipliedSubtotal:subtotal,multiplier:vikingRagnarokMultiplier(charge),progress};
}
