import {ExpansionSlot,ExpansionFrame,randomIndex as ri} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
type Token={symbol:string;raw:number;fixed:boolean};
/** DoubleDown's 12-respin, diamond collection and four-board feature structure.
 * Independent weights, adjacency, awards and board paths are local rules. */
export class FourCartSlot extends ExpansionSlot {
 // Keep ordinary line awards visible at BET20; bonus values use the separate factor.
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3))*Math.max(.7,this.payoutFactor);}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-hold';}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private pool(){return this.config.symbols.filter(s=>s.weight>0).map(s=>({...s,weight:s.id===this.id('scatter')?12:s.id===this.id('diamond')?3:s.weight}));}
 draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const pool=this.pool();return Array.from({length:15},()=>this.weighted(rng,pool));}
 private rich(id:string){return id===this.id('scatter')||id===this.id('diamond');}
 private bonus(b:string[],bet:number,rng:()=>number,base:SpinResult){
  const boards=Array.from({length:4},()=>new Map<number,Token>()),rounds=[base],snapshots:{frame:ExpansionFrame;entries:{cell:number;key:string;raw:number}[]}[]=[];let split=false,unlocked=1;
  const global=(panel:number,cell:number)=>split?Math.floor(panel/2)*30+Math.floor(cell/5)*10+panel%2*5+cell%5:cell;
  const clamp=(v:number)=>Math.min(1000000,Math.max(1,v));
  const add=(panel:number,cell:number,symbol:string)=>{const raw=symbol===this.id('multi')?[10,25,50,100][ri(rng,4)]:symbol===this.id('diamond')?clamp(Array.from(boards[panel].values()).filter(v=>!v.fixed).reduce((n,v)=>n+v.raw,0)):[1,2,3,5,8,10][ri(rng,6)];boards[panel].set(cell,{symbol,raw,fixed:symbol===this.id('multi')});};
  b.forEach((symbol,c)=>{if(symbol===this.id('scatter'))add(0,c,symbol);});b.forEach((symbol,c)=>{if(symbol===this.id('diamond'))add(0,c,symbol);});
  const frame=(action:ExpansionFrame['action'],caption:string,remaining:number,highlights:{panel:number;cell:number}[]=[],temporary:{panel:number;cell:number;symbol:string}[]=[])=>{
   const board=Array(split?60:15).fill(''),held:number[]=[],entries:{cell:number;key:string;raw:number}[]=[];
   for(let panel=0;panel<unlocked;panel++)for(const [cell,t]of boards[panel]){const c=global(panel,cell);board[c]=t.symbol;held.push(c);entries.push({cell:c,key:panel+':'+cell,raw:t.raw});}
   for(const v of temporary)board[global(v.panel,v.cell)]=v.symbol;
   const result=this.frame(board,action,caption,highlights.map(v=>global(v.panel,v.cell)),{held,remaining,cartBoards:{split,unlocked}},split?{columns:10,rows:6}:{columns:5,rows:3});snapshots.push({frame:result,entries});return result;
  };
  rounds.push(this.round(bet,[frame('state','금덩이·다이아몬드 고정 · 리스핀 12회',12)]));
  for(let turn=0;turn<12;turn++){
   const events:{panel:number;cell:number;symbol:string}[]=[],active=unlocked,left=11-turn;
   for(let panel=0;panel<active;panel++)for(let cell=0;cell<15;cell++){if(boards[panel].has(cell))continue;const roll=rng(),symbol=roll<.045?'scatter':roll<.052?'diamond':roll<.064?'tnt':roll<.085?'boost':roll<.088?'multi':'';if(symbol)events.push({panel,cell,symbol:this.id(symbol)});}
   const fs=[frame('reels','리스핀 '+(turn+1)+'/12 · 해금 '+unlocked+'판',left,[],events)];
   const landed=events.filter(e=>e.symbol===this.id('scatter')||e.symbol===this.id('multi'));for(const e of landed)add(e.panel,e.cell,e.symbol);if(landed.length)fs.push(frame('effect','새 금덩이 고정 · 상금 누적',left,landed));
   for(const e of events.filter(e=>e.symbol===this.id('diamond'))){add(e.panel,e.cell,e.symbol);fs.push(frame('collect','다이아몬드 · 같은 판의 금덩이와 다이아몬드 합계',left,[e]));}
   for(const e of events.filter(e=>e.symbol===this.id('boost'))){const factor=[2,3,5][ri(rng,3)],affected:{panel:number;cell:number}[]=[];for(const [c,t]of boards[e.panel])if(!t.fixed&&Math.abs(c%5-e.cell%5)<=1&&Math.abs(Math.floor(c/5)-Math.floor(e.cell/5))<=1){t.raw=clamp(t.raw*factor);affected.push({panel:e.panel,cell:c});}fs.push(frame('effect','폭발 ×'+factor+' · 인접 상금 증가',left,affected,[e]));}
   for(const e of events.filter(e=>e.symbol===this.id('tnt'))){if(!split){split=true;fs.push(frame('expand','TNT · 네 광차 보너스 시작',left,[e]));}else if(unlocked<4){unlocked++;fs.push(frame('effect','TNT · '+unlocked+'번째 릴판 해금',left,[e]));}}
   fs.push(frame('state','남은 리스핀 '+left+'회',left));rounds.push(this.round(bet,fs));
   if(boards.slice(0,unlocked).every(panel=>panel.size===15))break;
  }
  const awards=new Map<string,Win>();
  for(let panel=0;panel<unlocked;panel++)for(const [cell,t]of boards[panel])awards.set(panel+':'+cell,{line:-1,symbol:t.symbol,cells:[global(panel,cell)],amount:Math.round(bet*t.raw*this.payoutFactor),multiplier:t.raw*this.payoutFactor});
  for(let panel=0;panel<unlocked;panel++){const f=frame('win','광차 '+(panel+1)+' · 모은 상금 한 번 지급',0);f.wins=Array.from(boards[panel].keys()).map(c=>awards.get(panel+':'+c)!);f.cells=f.wins.flatMap(w=>w.cells);rounds.push(this.round(bet,[f]));}
  for(const snapshot of snapshots)snapshot.frame.coinAwards=snapshot.entries.map(e=>({cell:e.cell,win:awards.get(e.key)!,fraction:e.raw/boards[Number(e.key.split(':')[0])].get(Number(e.key.split(':')[1]))!.raw}));
  return this.finish(rounds,{featureOnly:true});
 }
 play(b:string[],bet:number,rng:()=>number){this.validate(b,bet,{columns:5,rows:3});const base=this.ordinary(b,bet),found=b.flatMap((id,c)=>this.rich(id)?[c]:[]);if(found.length<6)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(b,'trigger','금덩이·다이아몬드 '+found.length+'개 · 리스핀 12회',found));return this.bonus(b,bet,rng,base);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  // Binomial rich count conditioned on >=6, then uniform positions and
  // conditional rich/ordinary symbol pools: the same distribution as draw().
  const pool=this.pool(),rich=pool.filter(s=>this.rich(s.id)),plain=pool.filter(s=>!this.rich(s.id)),p=rich.reduce((n,s)=>n+s.weight,0)/pool.reduce((n,s)=>n+s.weight,0),weights:number[]=[];let choose=1;
  for(let n=0;n<=15;n++){if(n>=6)weights.push(choose*Math.pow(p,n)*Math.pow(1-p,15-n));choose=choose*(15-n)/(n+1);}
  let roll=rng()*weights.reduce((n,v)=>n+v,0),count=15;for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0){count=i+6;break;}}
  const positions=Array.from({length:15},(_,i)=>i);for(let i=14;i>0;i--){const j=ri(rng,i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}const selected=new Set(positions.slice(0,count)),board=Array.from({length:15},(_,c)=>this.weighted(rng,selected.has(c)?rich:plain));return this.purchaseFromResult(this.play(board,bet,rng));
 }
}
