import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {CHAOS_ART,ChaosLanding,chaosSymbol as symbol,chaosStart,chaosResolve,chaosLandingArt} from './ChaosFeature';

/** Full dedicated accumulator playback with explicit landing inputs. Source
 * payline disagreement and natural symbol/value probabilities remain unverified. */
export class ChaosPreviewSlot extends SlotMain {
 constructor(private readonly fixture='bonus'){super();}
 readonly columns=5;readonly rows=5;readonly mode='lines' as const;readonly paylines:number[][]=[];
 readonly bets=[...BET_LEVELS];readonly maxWin=10000;
 get bonusSymbol(){return symbol('scatter_poster');}
 readonly config:SlotConfig={id:'chaos-crew-x',title:'카오스 갱',subtitle:'CHAOS GANG',tag:'전용 보너스 체험',color:'#242337',accent:'#7bdaca',description:'해골은 릴 값에 더하기\n고양이는 릴 값에 곱하기\nEpic은 다섯 릴 전체에 적용\n성공하면 남은 회전 3회 복구\n세 번 실패한 뒤 전체 값 합산',symbols:CHAOS_ART.map(art=>({id:symbol(art),name:art==='cat_wild'?'WILD':art==='scatter_poster'?'보너스 포스터':art.replace(/_/g,' '),color:'#7bdaca',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('chaos-crew-x-'.length);if(!CHAOS_ART.includes(name))throw Error('Unknown Chaos art');return 'slot-art-delivered-v1/chaos-crew-x/v05/'+name;}
 spin(_bet?:number,_rng?:()=>number):SpinResult{throw Error('Chaos first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const opening=Array.from({length:25},(_,cell)=>symbol(CHAOS_ART[(cell+cell%5)%9]));
  if(this.fixture==='no-win')return{bet,board:opening,payout:0,wins:[]};
  [0,2,4].forEach(cell=>opening[cell]=this.bonusSymbol);
  const rounds:SpinResult[]=[{bet,board:opening,payout:0,wins:[]}];let state=chaosStart();
  while(state.remaining>0){
   const index=state.played,landings:ChaosLanding[]=[];
   if(this.fixture==='max-win'&&index===0)landings.push(...[0,1,2].map(cell=>({cell,kind:'multiply' as const,value:20,epic:true})));
   else if(this.fixture!=='empty'&&this.fixture!=='max-win'){
    if(index===0)landings.push({cell:12,kind:'add',value:2,epic:true},{cell:18,kind:'add',value:2,epic:false});
    if(index===1)landings.push({cell:10,kind:'add',value:20,epic:false});
    if(index===2)landings.push({cell:15,kind:'multiply',value:2,epic:false});
   }
   const feature=chaosResolve(state,landings,bet),board=Array(25).fill(symbol('inactive_mark'));
   landings.forEach(landing=>board[landing.cell]=chaosLandingArt(landing));state=feature.after;
   const award=feature.collection?.award;
   rounds.push({bet,board,chaosFeature:feature,wins:award?[award]:[],payout:award?.amount||0,freeSpinsAdded:feature.added||undefined,freeSpinsRemaining:state.remaining,roundLabel:`카오스 보너스 · ${state.played}회 · 남은 ${state.remaining}회`});
   if(state.played>20)throw Error('Chaos fixture did not finish');
  }
  const final=rounds[rounds.length-1];
  return{bet,board:[...final.board],wins:rounds.flatMap(round=>round.wins),payout:final.payout,rounds,freeSpinsAwarded:3,featureName:'카오스 갱 · 릴 수집',bonusEndReason:final.chaosFeature?.collection?.capReached?'max-win':'spins-exhausted'};
 }
}
