import {SYMBOL_FX_PALETTES} from './SymbolFxPalettes';

/** Prominent symbols get a rectangular electrical halo even on compact screens. */
export const ELECTRIC_SYMBOL_SLOTS=new Set([
 'gates-of-clouds','starlight-princessa','sweet-bananaza','moon-princessa','tome-of-madness',
 'rhino-grand-ways','fruit-party-pals','crypt-of-x','fire-in-dwarf-hole',
 'viking-runecrafty','seven-jewel-dig','buried-gate-chambers','glyph-archive',
 'rose-orbit-voyage','orbital-crystal-core','signal-stack-ruins','prism-split-forge',
 'sun-goddess-stack','cosmic-herd-cascade','renaissance-gem-fall','gem-express-upgrade','diamond-fuse-trail',
]);
export function symbolFxPalette(slot:string,symbol:string,fallback:string):readonly string[]{
 return SYMBOL_FX_PALETTES[slot+'/'+symbol]||[fallback,'#ffeab3'];
}
/** Half-strength colour, mixed with white for softer hit fills and sparks. */
export function softFxColour(colour:string){
 return '#'+colour.slice(1).match(/../g)!.map(v=>Math.round((parseInt(v,16)+255)/2).toString(16).padStart(2,'0')).join('');
}
export function hitBackground(slot:string,symbol:string,fallback:string){
 if(slot==='season-tile-garden')return softFxColour('#b86d1c');
 const palette=symbolFxPalette(slot,symbol,fallback),rgb=palette[0].slice(1).match(/../g)!.map(v=>parseInt(v,16));
 // Preserve the symbol hue while halving the previous colour strength.
 const peak=Math.max(...rgb,1),floor=Math.min(...rgb);
 return softFxColour('#'+rgb.map(v=>Math.round(48+(v-floor)/Math.max(peak-floor,1)*112).toString(16).padStart(2,'0')).join(''));
}
export function electricSymbol(slot:string,width:number,height:number){
 return ELECTRIC_SYMBOL_SLOTS.has(slot)||Math.min(width,height)>=86;
}
export const TUMBLE_FX_SECONDS=.56;
export const TUMBLE_FX_FULL_BUDGET=14;
