/** Engine/replay stakes retain historical values for saved feature state and calibration. */
export const BET_LEVELS=[20,30,40,50,70,100,150,200,250,300,350,400,450,500,600,700,800,900,1000,2000,3000,4000,5000,6000,7000,8000,9000,10000];
/** The only selectable stakes for new gameplay. */
export const PLAY_BET_LEVELS=BET_LEVELS.filter(bet=>bet>=100);
/** Wagers used by the existing calibration files; independent of UI ordering. */
export const CALIBRATED_BETS=[10,25,50,100,250,500,1000,2500,5000,10000];
export const normalizeBetLevel=(value:unknown)=>typeof value==='number'&&PLAY_BET_LEVELS.includes(value)?value:PLAY_BET_LEVELS[0];
