const choiceArt:Record<string,string[]>={
 'sumo-ring-hold':['5','4','unlock'],
 'dragon-ember-vault':['0','1'],
 'silver-mine-hold':['free','hold'],
 'frog-story-chapters':['page','double','boost'],
 'cruise-feature-builder':['1','0','double','vip'],
 'angel-devil-contract':['3','4'],
 'sun-goddess-stack':['rose','rose','rose','rose'],
 'builder-house-rise':['scatter','wheel'],
 'lantern-fire-link':['coin','free','free','free','free','free','coin'],
 'festival-drum-choice':['scatter','scatter','scatter','scatter','coin'],
 'heart-link-vault':['scatter','coin'],
 'jungle-height-fortune':['5','5','5'],
 'gladiator-lore':['arena_gate','beast_gate'],
 'golden-zodiac-choice':['0','1','2'],
 'starlit-cast':['0','1','2','3','4'],
 'red-cloak-expedition':['1','5','2'],
 'ember-pinball':['4','4'],
 'crystal-seal-breaker':['0','0','0'],
 'golden-city-atlas':['0','3','1'],
 'triple-compass':['1','0'],
};
export function featureChoiceIcon(id:string,index:number,symbols:readonly {id:string}[],label=''){
 const placeArt:Record<string,string>={'카페':'1','공원':'3','다리':'2','박물관':'7','광장':'wild','강변':'scatter'};
 const lobsterArt:Record<string,string>={'무료 5회':'wild','부표 탐험':'2','브라질':'octopus','호주':'kangaroo','메인':'pelican','받기':'wild','다시 선택':'pelican'};
 const suffix=id==='harvest-moon-fiesta'?(index?'wild':'scatter'):['lobster-harbor-choice','lobster-harbor-ways'].includes(id)?lobsterArt[label]:id==='lantern-fire-link'?(label==='불꽃 리스핀'||label==='미스터리'?'coin':'free'):id==='puppy-paris-path'?placeArt[label.split(' · ')[0]]:choiceArt[id]?.[index];
 const candidate=id+'-'+suffix;
 return symbols.find(symbol=>symbol.id===candidate)?.id||symbols[index%symbols.length]?.id||'';
}
export const CHOICE_CONFIRM_SECONDS=.06;
export const COVERED_AUTO_SECONDS=.1;
/** Square cards read left-to-right, with the last partial row centred. */
export function featureChoiceLayout(width:number,height:number,count:number,details=false,headerExtra=0){
 const columns=count===4?2:Math.min(3,count),rows=Math.ceil(count/columns),gap=12,padding=16;
 const cardWidth=Math.min(width-32,600),detailHeight=details?50:0;
 const side=Math.min(176,(cardWidth-padding*2-gap*(columns-1))/columns,(height-208-gap*(rows-1)-detailHeight*rows)/rows);
 const cardHeight=148+headerExtra+rows*(side+detailHeight)+gap*(rows-1),x=(width-cardWidth)/2,y=(height-cardHeight)/2;
 const cells=Array.from({length:count},(_,index)=>{
  const row=Math.floor(index/columns),col=index%columns,n=Math.min(columns,count-row*columns);
  return {left:x+(cardWidth-n*side-(n-1)*gap)/2+col*(side+gap),top:y+86+headerExtra+row*(side+detailHeight+gap),side};
 });
 return {x,y,cardWidth,cardHeight,detailHeight,cells};
}
