import type {SpinResult,Win} from './SlotMain';
export const CLASSIC_SYMBOLS=['cherry','lemon','orange','plum','grapes','watermelon','seven','scatter'] as const;
export const classicSymbol=(name:string)=>'realtime-vegas-'+name;
export interface ClassicPlayback {lineHits:{win:Win;totalBefore:number;totalAfter:number}[];sevenCells:number[];scatterCells:number[];}
/** Five reels/three rows observed in 777 Classic Hot. Only the supplied
 * observed line wins are staged; unknown scatter rules never mint a bonus. */
export function classicResult(board:string[],input:Win[],bet:number):SpinResult{
 if(board.length!==15||board.some(symbol=>!CLASSIC_SYMBOLS.some(name=>classicSymbol(name)===symbol))||!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid classic board');
 const seen=new Set<number>();let total=0;const lineHits:ClassicPlayback['lineHits']=[],wins:Win[]=[];
 for(const item of input){
  if(!Number.isInteger(item.line)||item.line<0||item.line>=5||seen.has(item.line)||!Number.isSafeInteger(item.amount)||item.amount<1||item.cells.length<3||item.cells.length>5||item.symbol===classicSymbol('scatter')||item.cells.some((cell,col)=>!Number.isInteger(cell)||cell<0||cell>=15||cell%5!==col||board[cell]!==item.symbol))throw Error('Invalid classic line');
  seen.add(item.line);const win={...item,cells:[...item.cells]},before=total;total+=win.amount;if(!Number.isSafeInteger(total))throw Error('Classic payout overflow');wins.push(win);lineHits.push({win,totalBefore:before,totalAfter:total});
 }
 return {bet,board:[...board],wins,payout:total,classicFeature:{lineHits,sevenCells:board.flatMap((id,cell)=>id===classicSymbol('seven')?[cell]:[]),scatterCells:board.flatMap((id,cell)=>id===classicSymbol('scatter')?[cell]:[])}};
}
